ALTER TABLE "dictionary_document_uploads" DROP CONSTRAINT "dictionary_document_uploads_quota";--> statement-breakpoint
ALTER TABLE "dictionary_document_uploads" ADD CONSTRAINT "dictionary_document_uploads_quota" CHECK ("dictionary_document_uploads"."observed_physical_bytes" >= 0 and "dictionary_document_uploads"."accounted_physical_bytes" >= "dictionary_document_uploads"."expected_size_bytes" and "dictionary_document_uploads"."accounted_physical_bytes" >= "dictionary_document_uploads"."observed_physical_bytes" and ("dictionary_document_uploads"."cleanup_state" not in ('waiting_capability_expiry', 'complete') or "dictionary_document_uploads"."quota_released_at" is not null) and ("dictionary_document_uploads"."quota_released_at" is null or ("dictionary_document_uploads"."cleanup_state" in ('running', 'waiting_capability_expiry', 'complete') and "dictionary_document_uploads"."data_versions_deleted_at" is not null and "dictionary_document_uploads"."quota_released_at" >= "dictionary_document_uploads"."data_versions_deleted_at")));